/**
 * Um item por aviso a entregar — e falha ALTO quando a fila não veio.
 *
 * Quem decide quem está parado, quem avisar, se pode avisar agora e para quem
 * vai o lead transferido é o banco (`montar_fila_do_funil`); quem monta o
 * texto é o site. Aqui só se entrega.
 *
 * Status fora de 200 estoura em vez de seguir vazio: execução verde com zero
 * envio é o modo de falha que já aconteceu neste projeto — e num alerta de
 * estagnação ele é invisível por semanas, que é exatamente o problema que
 * este funil existe para resolver.
 */

// >>> PREENCHA: WhatsApp de quem cuida do cadastro comercial, só dígitos com
//     DDI. Ex.: '5541999998888'. Vazio = o aviso de gestão não é enviado (e
//     sai registrado no ramo "Não enviado"). Constante e não `$env` pelo
//     mesmo motivo do outro workflow: acesso a variável de ambiente em nó
//     Code não está provado nesta instância, e se estiver bloqueado a
//     execução inteira estoura.
const WHATSAPP_GESTAO = '';

const r = $input.first().json;
const status = r.statusCode ?? 0;
const corpo = r.body ?? {};

if (status !== 200 || corpo.ok !== true) {
  throw new Error('Fila indisponível: HTTP ' + status + ' — ' + JSON.stringify(corpo).slice(0, 300));
}

const fila = Array.isArray(corpo.fila) ? corpo.fila : [];
const suprimidos = Array.isArray(corpo.suprimidos) ? corpo.suprimidos : [];
const semDestinatario = Array.isArray(corpo.sem_destinatario) ? corpo.sem_destinatario : [];

const itens = fila.map((a) => ({
  json: {
    tipo: 'vendedor',
    lead_id: a.lead_id,
    aviso: a.aviso,
    lead_nome: a.lead?.nome ?? '',
    etapa: a.lead?.etapa ?? '',
    minutos_parado: a.lead?.minutos_parado ?? null,
    destinatario_nome: a.destinatario?.nome ?? '',
    numero_whatsapp: a.destinatario?.whatsapp ?? '',
    mensagem: a.mensagem,
  },
}));

/**
 * O que a fila NÃO entregou e que depende de alguém arrumar.
 *
 * `fora_do_horario` e `alerta_recente` ficam de fora de propósito: são a
 * régua funcionando, não problema. `vendedor_sem_whatsapp` e
 * `sem_vendedor_disponivel` são cadastro faltando — e são silenciosos, que é
 * o que os torna perigosos: o lead segue parado e ninguém é cobrado.
 *
 * Só na primeira rodada do dia. Esta rotina acorda de hora em hora, e um
 * lembrete de cadastro repetido doze vezes vira ruído que se aprende a
 * ignorar — o oposto do que um alerta serve para fazer.
 */
const ACIONAVEIS = ['vendedor_sem_whatsapp', 'sem_vendedor_disponivel'];
const pendencias = suprimidos.filter((s) => ACIONAVEIS.includes(s.suprimido_por));

const horaLocal = Number(
  new Intl.DateTimeFormat('pt-BR', {
    timeZone: 'America/Sao_Paulo',
    hour: 'numeric',
    hour12: false,
  }).format(new Date()),
);
const primeiraRodadaDoDia = horaLocal === 8;

if (primeiraRodadaDoDia && (pendencias.length > 0 || semDestinatario.length > 0)) {
  const semWhats = pendencias.filter((s) => s.suprimido_por === 'vendedor_sem_whatsapp');
  const semDono = pendencias.filter((s) => s.suprimido_por === 'sem_vendedor_disponivel');
  const linhas = ['Leads parados que ninguém foi avisado:', ''];

  if (semWhats.length > 0) {
    linhas.push('Vendedor sem WhatsApp cadastrado:');
    for (const s of semWhats) {
      linhas.push('• ' + s.nome + ' — com ' + (s.responsavel ?? 'sem dono'));
    }
    linhas.push('');
    linhas.push('O telefone se cadastra no painel, em Usuários e permissões.');
    linhas.push('');
  }

  if (semDono.length > 0) {
    linhas.push('Sem vendedor disponível para receber:');
    for (const s of semDono) {
      linhas.push('• ' + s.nome + ' (' + s.etapa + ')');
    }
    linhas.push('');
    linhas.push('O rodízio precisa de pelo menos dois vendedores ativos com WhatsApp — ');
    linhas.push('a escolha exclui o dono atual, então com um só ninguém pode receber.');
  }

  if (semDestinatario.length > 0) {
    linhas.push('');
    linhas.push('Aviso montado sem destinatário (o número sumiu no meio do caminho): '
      + semDestinatario.length);
  }

  itens.push({
    json: {
      tipo: 'gestao',
      destinatario_nome: 'Gestão',
      numero_whatsapp: WHATSAPP_GESTAO,
      mensagem: linhas.join('\n'),
    },
  });
}

// Fila vazia é resultado bom, não erro — e precisa passar sem envio nenhum.
return itens;

/**
 * Fecha o rastro de cada envio.
 *
 * Sem devolução de desfecho: o rastro do lead já foi escrito pelo banco no
 * mesmo comando que montou a fila. O que se registra aqui é a ENTREGA, que é
 * a única parte que o banco não tem como saber.
 */
const resposta = $json;
const original = $('Distribuir os avisos').item.json;
const status = resposta.statusCode ?? 0;

return {
  json: {
    tipo: original.tipo,
    aviso: original.aviso ?? null,
    lead_nome: original.lead_nome ?? null,
    destinatario_nome: original.destinatario_nome,
    minutos_parado: original.minutos_parado ?? null,
    status,
    enviado: status < 300,
  },
};

/**
 * Quem não tinha número. Não é erro de execução — é cadastro faltando —, mas
 * precisa aparecer, senão o aviso de gestão some justamente quando o telefone
 * da gestão é o que está faltando.
 */
return {
  json: {
    tipo: $json.tipo,
    aviso: $json.aviso ?? null,
    lead_nome: $json.lead_nome ?? null,
    destinatario_nome: $json.destinatario_nome,
    enviado: false,
    motivo: $json.tipo === 'gestao'
      ? 'WHATSAPP_GESTAO não preenchido no nó "Distribuir os avisos"'
      : 'destinatário sem telefone em profiles.telefone_e164',
  },
};
